<script lang="ts">
  import{onDestroy}from'svelte';import{open}from'@tauri-apps/plugin-dialog';import{guessOs}from'#lib/api.ts';import{roadmapMediaApi}from'#lib/roadmap-media-api.ts';import{createJob,type JobHandle,type JobProgress}from'#lib/jobs.ts';
  import Notice from'#lib/ui/Notice.svelte';import CopyButton from'#lib/ui/CopyButton.svelte';import ProgressBar from'#lib/ui/ProgressBar.svelte';import MediaProvider from'#lib/ui/MediaProvider.svelte';
  const os=guessOs();let path=$state(''),provider=$state<'native'|'tesseract'>(os==='windows'?'native':'tesseract'),language=$state(os==='windows'?'en-US':'eng'),text=$state(''),error=$state(''),busy=$state(false),done=$state(false),progress=$state<JobProgress|null>(null);let requestId=0,job:JobHandle|null=null;
  async function choose(){const id=requestId;try{const selected=await open({multiple:false,filters:[{name:'Image',extensions:['png','jpg','jpeg','webp']}]});if(id===requestId&&typeof selected==='string'){path=selected;text='';done=false;}}catch(cause){if(id===requestId)error=String(cause);}}
  async function run(){const id=++requestId;busy=true;error='';done=false;text='';progress=null;job=createJob('recognize-text',next=>{if(id===requestId)progress=next;});try{const next=await job.run(jobId=>roadmapMediaApi.recognizeText(jobId,path,provider,language));if(id===requestId){text=next;done=true;}}catch(cause){if(id===requestId)error=String(cause);}finally{if(id===requestId){busy=false;job=null;}}}
  onDestroy(()=>{requestId++;void job?.cancel().catch(()=>{});});
</script>
<div class="tool" aria-busy={busy}><Notice kind="info">Recognizes text from your chosen local image. Windows OCR uses installed OS language packs; Tesseract uses your installed executable and language data. Nothing is uploaded. Images are limited to 40 million pixels; Windows OCR scales to its native dimension limit.</Notice>
  <label class="field"><span class="field-label">Recognition provider</span><select class="input" bind:value={provider} onchange={()=>language=provider==='native'?'en-US':'eng'} disabled={busy}><option value="native" disabled={os!=='windows'}>Windows OCR</option><option value="tesseract">Tesseract</option></select></label>
  {#if provider==='tesseract'}<MediaProvider provider="tesseract"/>{/if}
  <label class="field"><span class="field-label">{provider==='native'?'BCP 47 language code (for example en-US)':'Tesseract language code (for example eng or eng+deu)'}</span><input class="input" bind:value={language} disabled={busy}/></label>
  <div class="row"><button class="btn" onclick={choose} disabled={busy}>Choose image</button><span class="path">{path||'No image selected'}</span></div><div class="row"><button class="btn btn-primary" onclick={run} disabled={busy||!path||!language}>{busy?'Recognizing…':'Recognize text'}</button>{#if busy}<button class="btn" onclick={()=>job?.cancel().catch(cause=>error=String(cause))}>Cancel</button>{/if}</div>
  {#if busy && progress}<ProgressBar {progress}/>{/if}<div class="row"><span class="field-label" id="ocr-output">Recognized text</span><CopyButton {text}/></div><textarea class="textarea" aria-labelledby="ocr-output" value={text} readonly placeholder="Recognized text appears here."></textarea>
  {#if done}<Notice kind="success">{text.trim()?'Text recognition completed.':'No text was detected in this image.'}</Notice>{/if}{#if error}<Notice kind="error">{error}</Notice>{/if}
</div><style>.tool{display:grid;gap:var(--s-4)}.row{display:flex;gap:var(--s-3);align-items:center;flex-wrap:wrap}.path{overflow-wrap:anywhere;color:var(--text-2)}</style>
